/// <summary>
/// designe from AVA
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormDataSourceEventHandler(formDataSourceStr(AVAMSQCustVendAssignment, AVAMSQCustVendAssignment), FormDataSourceEventType::Activated),
 SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void AVAMSQCustVendAssignment_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    AVAMSQCustVendAssignment        custVemdAssignment = sender.cursor();
    FormRun                         formRun = sender.formRun();
    FormFunctionButtonControl       exceptionButton;

    exceptionButton = formRun.design().controlName('AVACustVendAssignmentExceptions');

    if (exceptionButton)
    {
        exceptionButton.enabled(custVemdAssignment.AVACustRel2TOS == NoYes::Yes);
    }
}
